### 5. THREE.JS TEXTURE LOADING PATTERN (Current Implementation)

**File:** `/c/Users/edn_y/renew_nineonelabs/resource/ts/ui/WorkCard.ts`

**Image Loading via Promise:**
```typescript
static loadImage(url: string): Promise<HTMLImageElement> {
  const trimmed = url.trim();
  return new Promise((resolve, reject) => {
    if (!trimmed) {
      reject(new Error("WorkCard: empty image url"));
      return;
    }
    const image = new Image();
    // Enable CORS if not data/blob URL
    if (!trimmed.startsWith("data:") && !trimmed.startsWith("blob:")) {
      image.crossOrigin = "anonymous";
    }
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error(`WorkCard: failed to load image ${trimmed}`));
    image.src = trimmed;  // <-- Trigger load
  });
}
```

**Canvas Texture Creation (from HTMLImageElement):**
```typescript
static buildTexture(
  proj: WorkProjectItem,
  size: WorkCardSize,
  image?: HTMLImageElement | null,
): THREE.CanvasTexture {
  const canvas = document.createElement("canvas");
  canvas.width = CANVAS_W * CANVAS_DPI_SCALE;
  canvas.height = height * CANVAS_DPI_SCALE;

  const ctx = canvas.getContext("2d");
  drawCardToContext(ctx, proj, size, image);  // <-- Draws image onto canvas

  const texture = new THREE.CanvasTexture(canvas);
  texture.flipY = false;
  texture.premultiplyAlpha = false;
  texture.anisotropy = 16;
  return texture;
}
```

**Update Texture with Loaded Image:**
```typescript
static updateTextureImage(
  texture: THREE.CanvasTexture,
  proj: WorkProjectItem,
  size: WorkCardSize,
  image: HTMLImageElement,
  renderOptions: WorkCardRenderOptions,
): void {
  const canvas = texture.image as HTMLCanvasElement;
  const ctx = canvas.getContext("2d");
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawCardToContext(ctx, proj, size, image);
  texture.needsUpdate = true;  // <-- Notify Three.js to re-upload
}
```

---

### 6. WORKS SCATTER (3D Canvas) REFERENCE IMPLEMENTATION

**File:** `/c/Users/edn_y/renew_nineonelabs/resource/ts/pages/works/render/WorksSceneManager.ts`

**Thumbnail Warming Pattern (lines 440–482):**

```typescript
// After scene is initialized, load thumbnails in batches
private warmThumbnails() {
  let index = 0;
  const batchSize = 4;

  const runBatch = async (): Promise<void> => {
    const slice = meshes.slice(index, index + batchSize);

    await Promise.all(
      slice.map(async (mesh) => {
        const userData = mesh.userData as WorkCardUserData;
        const material = mesh.material as THREE.MeshBasicMaterial;
        const map = material.map;  // THREE.CanvasTexture

        const thumb = userData.proj.thumbnailImage?.trim() ?? "";
        let img: HTMLImageElement;

        if (thumb) {
          try {
            img = await WorkCard.loadImage(thumb);  // <-- Load URL directly
          } catch {
            img = await ensureFallback();
          }
        } else {
          img = await ensureFallback();
        }

        // Update canvas texture with loaded image
        WorkCard.updateTextureImage(map, userData.proj, cardSize, img);

        // Store for later (e.g., video hover)
        userData.loadedImage = img;
      }),
    );

    if (index < meshes.length) {
      FrameScheduler.request(() => void runBatch());
    }
  };

  void runBatch();
}
```

**Key Points:**
1. `userData.proj.thumbnailImage` is a **full URL** from the API
2. **No texture loader** — images are loaded as `HTMLImageElement` via `Image()` constructor
3. Images are drawn onto a **Canvas**, then wrapped in `THREE.CanvasTexture`
4. Texture is attached to mesh material and updated with `texture.needsUpdate = true`
5. **Batch loading** with `Promise.all()` (4 at a time) + `FrameScheduler` to prevent frame drops

**Card User Data Type (lines 158–162):**
```typescript
export interface WorkCardUserData {
  proj: WorkProjectItem;
  detailPath: string;
  loadedImage?: HTMLImageElement | null;  // <-- Cached loaded image
}
```

