import * as THREE from "three";
import { SceneObject } from "../../core/SceneObject.js";
import type {
  PlanetObjectOptions,
  PlanetTweenProps,
} from "../../types/object.types.js";
import type { PlanetResolvedOptions } from "../../types/object-runtime.types.js";
import { Helpers } from "../../utils/Helpers.js";
import atmosphereVertexShader from "../../../shaders/earth/vertex.glsl?raw";

const PLANET_ATMOSPHERE_FRAGMENT_SHADER = `
varying vec3 vNormal;
varying vec3 eyeVector;
uniform float atmOpacity;
uniform float atmPowFactor;
uniform float atmMultiplier;
uniform vec3 atmColor;

void main() {
    float dotP = max(0.0, dot(vNormal, eyeVector));
    float factor = pow(dotP, atmPowFactor) * atmMultiplier;
    vec3 rimColor = mix(atmColor * 0.82, vec3(1.0), 0.28 + dotP * 0.18);
    gl_FragColor = vec4(rimColor, atmOpacity) * factor;
}
`;

export class Planet extends SceneObject<PlanetTweenProps> {
  private _options: Partial<PlanetObjectOptions> = {};
  private _geometry: THREE.SphereGeometry | null = null;
  private _atmosphereGeometry: THREE.SphereGeometry | null = null;
  private _material: THREE.MeshStandardMaterial | null = null;
  private _atmosphereMaterial: THREE.ShaderMaterial | null = null;
  private _mesh: THREE.Mesh<
    THREE.SphereGeometry,
    THREE.MeshStandardMaterial
  > | null = null;
  private _atmosphereMesh: THREE.Mesh<
    THREE.SphereGeometry,
    THREE.ShaderMaterial
  > | null = null;
  private _group: THREE.Group | null = null;
  private _textures: THREE.Texture[] = [];
  private _materials: THREE.Material[] = [];
  private _didPrewarm = false;
  private readonly _atmosphereUniforms = {
    atmOpacity: { value: 0.42 },
    atmPowFactor: { value: 4.8 },
    atmMultiplier: { value: 5.8 },
    atmColor: { value: new THREE.Color(1, 1, 1) },
  };

  setOptions(props: Partial<PlanetObjectOptions> | undefined): this {
    if (props != null) this._assignOptions(props);
    return this;
  }

  override getAnimationTarget(): THREE.Object3D | null {
    return this.getTimelineRoot();
  }

  override getTweenApplyMode(): "mergeAndSync" {
    return "mergeAndSync";
  }

  protected override getOptions(): Record<string, unknown> {
    return this._options as Record<string, unknown>;
  }

  protected override applyVisibility(visible: boolean): void {
    const root = this.getTimelineRoot();
    if (!root) return;
    root.visible = visible;
  }

  protected override syncFromOptions(): void {
    const options = this._resolveOptions();
    const root = this.getTimelineRoot();
    if (root) {
      Helpers.applyTransform(root, options);
      root.visible = options.visible;
    }
    if (this._material) {
      this._material.color.setHex(options.color);
      this._material.roughness = options.roughness;
      this._material.metalness = options.metalness;
      this._material.bumpScale = options.bumpScale;
    }
    this._atmosphereUniforms.atmOpacity.value = options.atmosphereOpacity;
    this._atmosphereUniforms.atmPowFactor.value = options.atmospherePowFactor;
    this._atmosphereUniforms.atmMultiplier.value = options.atmosphereMultiplier;
    this._atmosphereUniforms.atmColor.value.setRGB(
      options.atmosphereColor[0],
      options.atmosphereColor[1],
      options.atmosphereColor[2],
    );
  }

  override async runObject(): Promise<void> {
    const options = this._resolveOptions();
    const texturePaths = this._resolveTexturePaths(options);
    const [dayMap, bumpMap] = await Promise.all([
      this._loadTexture(texturePaths.dayTextureUrl, true),
      this._loadTexture(texturePaths.bumpTextureUrl, false),
    ]);
    this._prepareTextures([dayMap, bumpMap]);
    this._textures.push(dayMap, bumpMap);

    this._geometry = new THREE.SphereGeometry(
      options.radius,
      options.widthSegments,
      options.heightSegments,
    );
    this._material = new THREE.MeshStandardMaterial({
      color: options.color,
      map: dayMap,
      bumpMap,
      bumpScale: options.bumpScale,
      roughness: options.roughness,
      metalness: options.metalness,
    });
    this._materials.push(this._material);
    this._mesh = new THREE.Mesh(this._geometry, this._material);
    this._mesh.name = "planetMesh";

    this._atmosphereGeometry = new THREE.SphereGeometry(
      options.radius * options.atmosphereScale,
      options.widthSegments,
      options.heightSegments,
    );
    this._atmosphereMaterial = new THREE.ShaderMaterial({
      vertexShader: atmosphereVertexShader as string,
      fragmentShader: PLANET_ATMOSPHERE_FRAGMENT_SHADER,
      uniforms: this._atmosphereUniforms,
      blending: THREE.AdditiveBlending,
      side: THREE.BackSide,
      transparent: true,
      depthWrite: false,
    });
    this._materials.push(this._atmosphereMaterial);
    this._atmosphereMesh = new THREE.Mesh(
      this._atmosphereGeometry,
      this._atmosphereMaterial,
    );
    this._atmosphereMesh.name = "planetAtmosphereMesh";

    this._group = new THREE.Group();
    this._group.name = "planetGroup";
    this._group.add(this._mesh);
    this._group.add(this._atmosphereMesh);

    this.attachToTimelineRoot(this._group, "planetRoot");
    this.syncFromOptions();
    const root = this.getTimelineRoot();
    if (!root) return;
    this._prewarmSceneCompile(root);
  }

  override runUpdate(_deltaTime: number): void {}

  override dispose(): void {
    this._geometry?.dispose();
    this._atmosphereGeometry?.dispose();
    this._materials.forEach((material) => material.dispose());
    this._textures.forEach((texture) => texture.dispose());
    this._geometry = null;
    this._atmosphereGeometry = null;
    this._material = null;
    this._atmosphereMaterial = null;
    this._mesh = null;
    this._atmosphereMesh = null;
    this._group = null;
    this._materials = [];
    this._textures = [];
    this._didPrewarm = false;
    super.dispose();
  }

  private _assignOptions(props: Partial<PlanetObjectOptions>): void {
    const next: Partial<PlanetObjectOptions> = {
      ...this._options,
      ...props,
    };
    if (props.position) next.position = { ...props.position };
    if (props.rotation) next.rotation = { ...props.rotation };
    if (props.scale) next.scale = { ...props.scale };
    if (props.effects) next.effects = { ...props.effects };
    this._options = next;
  }

  private _resolveOptions(): PlanetResolvedOptions {
    const options = this._options;
    return {
      radius: options.radius ?? 1,
      widthSegments: options.widthSegments ?? 32,
      heightSegments: options.heightSegments ?? 24,
      color: options.color ?? 0xffffff,
      dayTextureUrl: options.dayTextureUrl ?? "",
      bumpTextureUrl: options.bumpTextureUrl ?? "",
      bumpScale: options.bumpScale ?? 0.018,
      roughness: options.roughness ?? 0.42,
      metalness: options.metalness ?? 0.05,
      atmosphereScale: options.atmosphereScale ?? 1.08,
      atmosphereOpacity: options.atmosphereOpacity ?? 0.42,
      atmospherePowFactor: options.atmospherePowFactor ?? 4.8,
      atmosphereMultiplier: options.atmosphereMultiplier ?? 5.8,
      atmosphereColor: [
        options.atmosphereColor?.[0] ?? 1,
        options.atmosphereColor?.[1] ?? 1,
        options.atmosphereColor?.[2] ?? 1,
      ],
      position: {
        x: options.position?.x ?? 0,
        y: options.position?.y ?? 0,
        z: options.position?.z ?? 0,
      },
      rotation: {
        x: options.rotation?.x ?? 0,
        y: options.rotation?.y ?? 0,
        z: options.rotation?.z ?? 0,
      },
      scale: {
        x: options.scale?.x ?? 1,
        y: options.scale?.y ?? 1,
        z: options.scale?.z ?? 1,
      },
      visible: options.visible ?? true,
    };
  }

  private _resolveTexturePaths(options: PlanetResolvedOptions): {
    dayTextureUrl: string;
    bumpTextureUrl: string;
  } {
    const dayTextureUrl = options.dayTextureUrl.trim();
    const bumpTextureUrl = options.bumpTextureUrl.trim();
    if (!dayTextureUrl || !bumpTextureUrl) {
      throw new Error("Planet texture paths are required.");
    }
    return {
      dayTextureUrl: this.resolveAssetPath(dayTextureUrl),
      bumpTextureUrl: this.resolveAssetPath(bumpTextureUrl),
    };
  }

  private async _loadTexture(
    url: string,
    sRgb: boolean,
  ): Promise<THREE.Texture> {
    const texture = this._context?.loadTexture
      ? await this._context.loadTexture(url)
      : await new Promise<THREE.Texture>((resolve, reject) => {
          new THREE.TextureLoader().load(url, resolve, undefined, reject);
        });
    if (sRgb) texture.colorSpace = THREE.SRGBColorSpace;
    return texture;
  }

  private _prepareTextures(textures: THREE.Texture[]): void {
    const prepareTexture = this._context?.prepareTexture;
    if (!prepareTexture) return;
    textures.forEach((texture) => prepareTexture(texture));
  }

  private _prewarmSceneCompile(root: THREE.Object3D): void {
    if (this._didPrewarm) return;
    const compileScene = this._context?.compileScene;
    if (!compileScene) return;
    const previousVisible = root.visible;
    root.visible = true;
    compileScene();
    root.visible = previousVisible;
    this._didPrewarm = true;
  }
}

