92	  private _intersectionObserver: IntersectionObserver | null = null;
93	  private _rendering = false;
94	  private _disposed = false;
95	  private _canvas: HTMLCanvasElement | null = null;
96	  private _scrollProgress = 0;
97	  private _rotationStrategy: ProofRotationStrategy;
