234	    }
235	    return null;
236	  }
237	
238	  private _addCard(
239	    group: THREE.Group,
240	    index: number,
241	    total: number,
242	    texture: THREE.Texture | null,
243	    radius: number,
244	  ): void {
245	    const angle = (index / total) * Math.PI * 2;
246	    const x = radius * Math.cos(angle);
247	    const z = radius * Math.sin(angle);
248	
249	    const geo = new THREE.PlaneGeometry(CARD_WIDTH, CARD_HEIGHT);
250	    this._geometries.push(geo);
251	
252	    const mat = createCardMaterial(
253	      texture,
254	      FALLBACK_COLORS[index % FALLBACK_COLORS.length],
255	    );
256	    this._materials.push(mat);
257	
258	    const mesh = new THREE.Mesh(geo, mat);
259	    mesh.position.set(x, 0, z);
260	    // rotation.y so the front face (+Z normal) points radially outward from center
261	    mesh.rotation.y = Math.PI / 2 - angle;
262	    group.add(mesh);
263	  }
264	
265	  private readonly _tick = (): void => {
266	    if (this._disposed || !this._rendering) return;
267	    const p = this._scrollProgress;
268	    const speed = this._rotationStrategy.next();
269	    if (this._group) this._group.rotation.y += speed;
270	    if (this._camera) {
271	      this._camera.position.y = 3 - p * 3;
272	      this._camera.lookAt(0, 0, 0);
273	    }
274	    if (this._renderer && this._scene && this._camera) {
275	      this._renderer.render(this._scene, this._camera);
276	    }
277	    this._rafId = requestAnimationFrame(this._tick);
278	  };
279	
280	  private _startRaf(): void {
281	    if (this._rafId !== null || this._disposed) return;
282	    this._rendering = true;
283	    this._rafId = requestAnimationFrame(this._tick);
284	  }
285	
286	  private _stopRaf(): void {
287	    this._rendering = false;
288	    if (this._rafId !== null) {
289	      cancelAnimationFrame(this._rafId);
290	      this._rafId = null;
291	    }
292	  }
293	
294	  private _syncSize(): void {
295	    const canvas = this._canvas;
296	    const renderer = this._renderer;
297	    const camera = this._camera;
298	    if (!canvas || !renderer || !camera) return;
299	    const w = canvas.clientWidth;
300	    const h = canvas.clientHeight;
301	    if (w <= 0 || h <= 0) return;
302	    renderer.setSize(w, h, false);
303	    camera.aspect = w / h;
304	    camera.updateProjectionMatrix();
305	  }
306	
307	  private _observeResize(): void {
308	    if (!this._canvas) return;
309	    this._resizeObserver = new ResizeObserver(() => this._syncSize());
310	    this._resizeObserver.observe(this._canvas);
311	  }
312	
313	  private _observeVisibility(): void {
314	    if (!this._canvas) return;
315	    this._intersectionObserver = new IntersectionObserver(
316	      (entries) => {
317	        if (entries[0]?.isIntersecting) {
318	          this._startRaf();
319	        } else {
320	          this._stopRaf();
321	        }
322	      },
323	      { threshold: 0 },
324	    );
325	    this._intersectionObserver.observe(this._canvas);
326	  }
327	}
